module tone_gen (
    input  wire       clk,
    input  wire       rst_n,
    input  wire [6:0] midi_note,
    output reg        speaker
);
    reg [19:0] target;
    always @(*) begin
        case (midi_note)
            7'd25: target = 20'd721546;
            7'd26: target = 20'd681049;
            7'd27: target = 20'd642824;
            7'd28: target = 20'd606745;
