            7'd86: target = 20'd21283;
            7'd87: target = 20'd20088;
            7'd88: target = 20'd18961;
            7'd89: target = 20'd17897;
            7'd90: target = 20'd16892;
            7'd91: target = 20'd15944;
            7'd92: target = 20'd15049;
            7'd93: target = 20'd14205;
            7'd94: target = 20'd13407;
            7'd95: target = 20'd12655;
            default: target = 20'd0;
        endcase
    end

    reg [19:0] counter;
    always @(posedge clk) begin
        if (!rst_n || target == 20'd0) begin
            counter <= 20'd0;
            speaker <= 1'b0;
        end else if (counter >= target) begin
            counter <= 20'd0;
            speaker <= ~speaker;
        end else begin
            counter <= counter + 20'd1;
        end
    end
endmodule

module tt_um_bobert3d_jvjk_ajrbang (
    input  wire [7:0] ui_in,    // ui_in[0] = Play (1) / Pause (0)
    output wire [7:0] uo_out,   // 8 Melodic Instrument Audio Channels
    input  wire [7:0] uio_in,
    output wire [7:0] uio_out,  // 8 Drum Trigger Channels
    output wire [7:0] uio_oe,   // Set all uio pins to Output mode
    input  wire       ena,
    input  wire       clk,
    input  wire       rst_n
);
    // Machine 2: 140 BPM 16th-Note Beat Timer with Auto-Loop
    reg [23:0] tempo_cnt;
    reg [10:0] step;

    always @(posedge clk) begin
        if (!rst_n) begin
            tempo_cnt <= 24'd0;
            step      <= 11'd0;
        end else if (ui_in[0]) begin
            if (tempo_cnt >= 24'd5357143) begin
                tempo_cnt <= 24'd0;
                step      <= (step >= 11'd1599) ? 11'd0 : step + 11'd1;
            end else begin
                tempo_cnt <= tempo_cnt + 24'd1;
            end
        end
    end

    // Melodic Channel 0 (MIDI Track 0)
